// MODE 'check' = report only; 'write' = write approved fixes to Lokalise
// Applied 19.10.26: exec 870884 (363), 870914 (11), 870960 (96). Back to 'check'; switch to 'write' deliberately for a new run.
const MODE = 'check';
const PID = '185916266aa3d6649ca6f7.57851232';   // BrainIQtest
const AUTO = 'maria@efuturemedia.com';            // automation account: only strings last edited by it are changed
const BATCH_CHARS = 14000;
const EXCLUDE = /^members-content::challenges::(2035|2041)::answers/;
const ONLY = null;                                // e.g. /^members-content::lessons::1646::/ to limit a run
return [{ json: { mode: MODE, pid: PID, auto: AUTO, batch_chars: BATCH_CHARS, exclude: EXCLUDE.source, only: ONLY ? ONLY.source : '', segments: true } }];

const cfg = $('Config').first().json;
const NL = String.fromCharCode(10);
const ONLY = cfg.only ? new RegExp(cfg.only) : null;
const rows = []; const errors = [];
for (const it of $('Fetch Keys').all()) {
  const b = it.json.body || {};
  if (it.json.statusCode && it.json.statusCode !== 200) { errors.push('keys ' + it.json.statusCode); }
  for (const k of (b.keys || [])) {
    if (k.is_archived || k.is_plural) { continue; }
    const kn = (typeof k.key_name === 'object') ? (k.key_name.web || k.key_name.other || '') : k.key_name;
    if (kn.indexOf('members-content::') !== 0) { continue; }
    if (ONLY && !ONLY.test(kn)) { continue; }
    let en = '', es = '', by = '';
    for (const tr of (k.translations || [])) {
      const v = typeof tr.translation === 'string' ? tr.translation : JSON.stringify(tr.translation);
      if (tr.language_iso === 'en') { en = v; }
      if (tr.language_iso === 'es') { es = v; by = tr.modified_by_email || ''; }
    }
    if (!es.trim()) { continue; }
    rows.push({ id: k.key_id, k: kn, en: en, es: es, by: by, ns: kn.split('::').slice(0, 3).join('::') });
  }
}
if (errors.length) { throw new Error('Fetch failed: ' + errors.join(', ')); }
const GER = /^\s*(?:\d+\.\s*)?[A-Za-z\u00C0-\u017F]+(?:ando|iendo|yendo)\b/i;
function issues(r) {
  const out = [];
  const txt = r.es.replace(/<[^>]+>/g, '');
  if (/:[ \t\u00a0]*[\u00ab"\u201c(]?[A-Z\u00c1\u00c9\u00cd\u00d3\u00da\u00d1\u00dc]/.test(txt)) { out.push('uppercase after colon'); }
  if (/(^|[^\p{L}])retos?([^\p{L}]|$)/iu.test(txt)) { out.push('reto -> desaf\u00edo'); }
  if (/["\u201c\u201d]/.test(txt)) { out.push('quotes -> \u00ab\u00bb'); }
  if (/(^|[^\p{L}])lag([^\p{L}]|$)/iu.test(txt)) { out.push('lag -> retraso'); }
  const heads = [];
  if (/::title$/.test(r.k)) { heads.push(txt); }
  const re = /<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi; let m;
  while ((m = re.exec(r.es)) !== null) { heads.push(m[1].replace(/<[^>]+>/g, '')); }
  if (heads.some(function (h) { return GER.test(h); })) { out.push('gerund in title/heading'); }
  return out;
}
function segs(s) { return s.split(/(<[^>]+>)/).filter(function (p, i) { return i % 2 === 0 && p.trim(); }).map(function (p) { return p.trim(); }); }
const byNs = {};
for (const r of rows) { (byNs[r.ns] = byNs[r.ns] || []).push(r); }
const cand = {}; const skippedLinguist = [];
for (const r of rows) {
  const is = issues(r);
  if (!is.length) { continue; }
  if (r.by !== cfg.auto) { skippedLinguist.push({ k: r.k, by: r.by, issues: is }); continue; }
  cand[r.id] = { r: r, is: is };
}
for (const id in Object.assign({}, cand)) {
  const c = cand[id];
  if (c.is.indexOf('gerund in title/heading') === -1) { continue; }
  for (const s of (byNs[c.r.ns] || [])) {
    if ((/::title$/.test(s.k) || /::steps:::0$/.test(s.k)) && !cand[s.id] && s.by === cfg.auto) { cand[s.id] = { r: s, is: ['keep identical to the lesson title / opening <h2>'] }; }
  }
}
const SYS = [
'You are a senior Spanish (Spain) copy editor for the BrainIQ members area (brain-training lessons and knowledge tests).',
'You receive Spanish strings together with the issues detected in each. Apply ONLY the corrections below and change nothing else: no rewording, no other punctuation, spacing or capitalization changes.',
'1. Lowercase after a colon: the word right after \':\' starts in lowercase (\'Beneficio: entrena\u2026\', \'es superior: el pensamiento\u2026\'), also when the colon ends one piece and the word starts the next piece. Keep the capital for proper nouns, acronyms (IA, IQ, TDAH), titles of works and direct quotations.',
'2. \'reto\' / \'retos\' used as a noun meaning challenge \u2192 \'desaf\u00edo\' / \'desaf\u00edos\', adjusting agreeing articles, determiners and adjectives. Leave verbs (retar, r\u00e9tate) unchanged.',
'3. Quotation marks: first-level quotes become Spanish angular quotes \u00ab\u2026\u00bb; quotes inside them become \u201c\u2026\u201d.',
'4. The English word \'lag\' \u2192 \'retraso\' (\'lag cognitivo\' \u2192 \'retraso cognitivo\').',
'5. Titles and headings must not start with a gerund: rephrase with a noun or an infinitive keeping the meaning.',
(cfg.segments ? 'Each string is given as "segments": the text pieces between its HTML tags, in order. For every string you change, return a JSON ARRAY of the corrected pieces with exactly the same number of items in the same order; every piece must stay non-empty. Return ONLY a JSON object {"<key_id>": ["<piece>", …]} with the strings you changed.' : 'Keep every HTML tag, line break, tab and space exactly as in the input. Return ONLY a JSON object {"<key_id>": "<corrected string>"} with the strings you changed; omit strings that need no change.')
].join(NL);
const list = Object.values(cand).sort(function (a, b) { return a.r.k.localeCompare(b.r.k, 'en', { numeric: true }); });
const out = []; let cur = []; let size = 0;
function flush() {
  if (!cur.length) { return; }
  const items = cur.map(function (c) { const o = { key_id: String(c.r.id), key: c.r.k, issues: c.is }; if (cfg.segments) { o.segments = segs(c.r.es); } else { o.es = c.r.es; } return o; });
  out.push({ json: { n: cur.length, old: cur.map(function (c) { return { id: c.r.id, k: c.r.k, es: c.r.es, is: c.is }; }),
    body: JSON.stringify({ model: 'gpt-4.1', temperature: 0, max_tokens: 32768, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(items) }] }) } });
  cur = []; size = 0;
}
let lastNs = '';
for (const c of list) {
  if (size > cfg.batch_chars && c.r.ns !== lastNs) { flush(); }
  cur.push(c); size += c.r.es.length; lastNs = c.r.ns;
}
flush();
const counts = {}; for (const c of list) { for (const i of c.is) { counts[i] = (counts[i] || 0) + 1; } }
for (const o of out) { o.json.meta = { members_es: rows.length, candidates: list.length, by_issue: counts, skipped_linguist: skippedLinguist, batches: out.length }; }
return out;

const batches = $('Candidates').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
const TAGRE = /<[^>]+>/g;
const SPLIT = /(<[^>]+>)/;
const PH = /%\d*\$?[sd]|\{\{[^}]+\}\}|\{[^{}]+\}|\[%[^\]]*\]/g;
function tags(s) { return JSON.stringify((s.match(TAGRE) || []).map(function (t) { return t.toLowerCase(); })); }
function plain(s) { return s.replace(TAGRE, ''); }
// lowercase letter starting a new sentence (after . ? ! … optionally followed by closing quote/paren) = forbidden
const SENT = /[.?!\u2026][\u00bb\u201d)]?[\s\u00a0]+[a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00f1\u00fc]/g;
function sentCount(s) { return (plain(s).match(SENT) || []).length; }
function rebuildSeg(old, pieces) {
  const ep = old.split(SPLIT); const out = []; let j = 0;
  for (let i = 0; i < ep.length; i++) {
    const p = ep[i];
    if (i % 2 === 1 || !p.trim()) { out.push(p); continue; }
    const t = pieces[j++];
    if (typeof t !== 'string' || !t.trim()) { return null; }
    out.push(p.match(/^\s*/)[0] + t.trim() + p.match(/\s*$/)[0]);
  }
  return j === pieces.length ? out.join('') : null;
}
const changes = []; const rejected = []; const callErr = [];
for (let i = 0; i < batches.length; i++) {
  const b = batches[i]; const r = res[i] || {};
  let map = null;
  try { const raw = String(r.choices[0].message.content); map = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
  catch (e) { callErr.push({ batch: i, err: r.error ? JSON.stringify(r.error).slice(0, 200) : String(e.message || e) }); continue; }
  if (map && map.t && typeof map.t === 'object') { map = map.t; }
  for (const o of b.old) {
    let nv = map[String(o.id)];
    if (Array.isArray(nv)) { nv = rebuildSeg(o.es, nv); if (nv === null) { rejected.push({ k: o.k, why: 'segment count/empty piece' }); continue; } }
    if (typeof nv !== 'string' || nv === o.es) { continue; }
    let why = '';
    if (!nv.trim()) { why = 'empty'; }
    else if (tags(nv) !== tags(o.es)) { why = 'HTML tags changed'; }
    else if ((o.es.match(PH) || []).sort().join('|') !== (nv.match(PH) || []).sort().join('|')) { why = 'placeholders changed'; }
    else if (sentCount(nv) > sentCount(o.es)) { why = 'lowercased a sentence start (after . ? !)'; }
    else { const ratio = nv.length / o.es.length; if (ratio < 0.85 || ratio > 1.2) { why = 'length changed too much (' + ratio.toFixed(2) + ')'; } }
    if (why) { rejected.push({ k: o.k, why: why }); continue; }
    changes.push({ id: o.id, k: o.k, is: o.is, old: o.es, new: nv });
  }
}
const meta = (batches[0] || {}).meta || {};
return [{ json: { meta: meta, n_changes: changes.length, rejected: rejected, call_errors: callErr, changes: changes } }];

// nothing passes in MODE 'check'; excluded keys never pass
const cfg = $('Config').first().json;
if (cfg.mode !== 'write') { return []; }
const ex = new RegExp(cfg.exclude);
const ch = ($input.first().json.changes || []).filter(function (c) { return !ex.test(c.k); });
const out = [];
for (let i = 0; i < ch.length; i += 100) { const part = ch.slice(i, i + 100); out.push({ json: { ids: part.map(function (c) { return c.id; }).join(','), changes: part } }); }
return out;

// guard: write only if live ES still equals the text we fixed and the last editor is still the automation account
const cfg = $('Config').first().json;
const ch = $('Gate').item.json.changes;
const b = $json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { for (const t of (k.translations || [])) { if (t.language_iso === 'es') { live[k.key_id] = { t: typeof t.translation === 'string' ? t.translation : '', by: t.modified_by_email || '', arch: k.is_archived }; } } }
const keys = []; const skipped = [];
for (const c of ch) {
  const L = live[c.id];
  if (!L || L.arch || L.t !== c.old || L.by !== cfg.auto) { skipped.push(c.k); continue; }
  keys.push({ key_id: c.id, translations: [{ language_iso: 'es', translation: c.new, is_unverified: true }] });
}
return { json: { n: keys.length, skipped: skipped, body: JSON.stringify({ keys: keys }) } };
